const crypto = require('crypto');
const allowed = [
  ['linkedin.com', /\/jobs\/view\//i, 'linkedin'],
  ['pracuj.pl', /\/(?:praca|oferta-pracy)\//i, 'pracuj'],
  ['justjoin.it', /\/(?:job-offer|offers|oferty-pracy)\//i, 'justjoinit'],
  ['nofluffjobs.com', /\/(?:job|pl\/job)\//i, 'nofluffjobs'],
  ['theprotocol.it', /\/filtry\/|\/szczegoly\//i, 'theprotocol'],
  ['bulldogjob.pl', /\/companies\/jobs\//i, 'bulldogjob'],
  ['rocketjobs.pl', /\/oferta-pracy\//i, 'rocketjobs'],
  ['wellfound.com', /\/jobs\//i, 'wellfound'],
  ['remoteok.com', /\/remote-jobs\//i, 'remoteok'],
  ['weworkremotely.com', /\/remote-jobs\//i, 'weworkremotely']
];
const clean = value => String(value).replace(/&amp;/g, '&').replace(/[)>\]}'".,;]+$/g, '');
const unwrap = raw => {
  let value = clean(raw);
  for (let i = 0; i < 3; i++) {
    let parsed;
    try { parsed = new URL(value); } catch { return null; }
    const nested = ['url', 'u', 'target', 'redirect', 'redirect_url'].map(key => parsed.searchParams.get(key)).find(Boolean);
    if (!nested) break;
    try { value = decodeURIComponent(nested); } catch { value = nested; }
  }
  try {
    const url = new URL(value);
    url.hash = '';
    for (const key of [...url.searchParams.keys()]) if (/^(utm_|trk|tracking|ref|source|campaign|mc_)/i.test(key)) url.searchParams.delete(key);
    return url;
  } catch { return null; }
};
const found = new Map();
for (const item of $input.all()) {
  const blob = JSON.stringify(item.json);
  const urls = blob.match(/https?:\/\/[^\s<>]+/gi) || [];
  for (const raw of urls) {
    const url = unwrap(raw);
    if (!url || url.protocol !== 'https:') continue;
    const host = url.hostname.toLowerCase().replace(/^www\./, '');
    const match = allowed.find(([domain, path]) => (host === domain || host.endsWith('.' + domain)) && path.test(url.pathname));
    if (!match) continue;
    const normalized = url.href;
    const id = crypto.createHash('sha256').update(normalized).digest('hex').slice(0, 12);
    found.set(id, { id, url: normalized, status: 'new', source: match[2], title: '', company: '', location: '', added_at: new Date().toISOString(), decided_at: '', draft_link: '', notes: 'Imported automatically from Gmail label Job Alerts' });
  }
}
return [...found.values()].map(json => ({ json }));
